polyglot/analysis.py:
"""Basic blocks, reachability, liveness and next use for typed IR optimization."""

from collections import deque

TEMP_FIELDS = {
    "STORE": ("value",), "MOVE": ("value",), "UNARY": ("value",),
    "WIDEN": ("value",), "FORMAT": ("value",), "BINARY": ("left", "right"),
    "ARRAY_NEW": ("size",), "ARRAY_GET": ("array", "index"),
    "ARRAY_SET": ("array", "index", "value"), "ARRAY_CHECK": ("array", "index"),
    "ARRAY_LENGTH": ("array",), "ARRAY_SIZE_CHECK": ("array", "size"),
    "BRANCH": ("condition",), "RETURN_VALUE": ("value",), "ASSERT": ("condition",),
}
TERMINATORS = {"JUMP", "BRANCH", "RETURN_VALUE", "RETURN_VOID", "TRAP"}


def temp_access(instruction: dict) -> tuple[set[int], set[int]]:
    uses = {instruction[key] for key in TEMP_FIELDS.get(instruction["op"], ())}
    if instruction["op"] in ("CALL", "OUTPUT", "ARRAY_BUILD"):
        uses.update(instruction["args"])
    dest = instruction.get("dest")
    return uses, {dest} if dest is not None else set()


def analyze_function(fn: dict) -> dict:
    code = fn["instructions"]
    labels = {i["label"]: n for n, i in enumerate(code) if i["op"] == "LABEL"}
    # 1. Partition the real instruction stream at leaders and terminators.
    leaders = {0, *labels.values()}
    for n, instruction in enumerate(code[:-1]):
        if instruction["op"] in TERMINATORS:
            leaders.add(n + 1)
    starts = sorted(leaders)
    if len(starts) > 120:
        return {"id": fn["id"], "name": fn["name"], "omitted": "More than 120 basic blocks."}
    blocks, owners = [], {}
    for bid, start in enumerate(starts):
        end = starts[bid + 1] if bid + 1 < len(starts) else len(code)
        for n in range(start, end):
            owners[n] = bid
        blocks.append({"id": bid, "start": start, "end": end, "successors": [], "predecessors": []})
    # 2. Resolve symbolic targets and retain the kind of each control-flow edge.
    edges = []
    for block in blocks:
        last = code[block["end"] - 1]
        targets = []
        if last["op"] == "BRANCH":
            targets = [(owners[labels[last[key]]], key) for key in ("true", "false")]
        elif last["op"] == "JUMP":
            targets = [(owners[labels[last["target"]]], "jump")]
        elif last["op"] not in TERMINATORS and block["id"] + 1 < len(blocks):
            targets = [(block["id"] + 1, "fallthrough")]
        for target, kind in targets:
            edges.append({"from": block["id"], "to": target, "kind": kind})
            if target not in block["successors"]:
                block["successors"].append(target)
                blocks[target]["predecessors"].append(block["id"])
    # 3. A block uses a temporary only if it reads it before a local definition.
    uses, defs, live_in, live_out = [], [], [], []
    for block in blocks:
        used, defined = set(), set()
        for instruction in code[block["start"]:block["end"]]:
            read, written = temp_access(instruction)
            used.update(read - defined)
            defined.update(written)
        uses.append(used)
        defs.append(defined)
        live_in.append(set())
        live_out.append(set())
    # 4. Solve backwards to a fixed point; only affected predecessors need revisiting.
    pending = deque(reversed(range(len(blocks))))
    queued = set(range(len(blocks)))
    updates = 0
    while pending:
        bid = pending.popleft()
        queued.remove(bid)
        updates += 1
        outgoing = set().union(*(live_in[s] for s in blocks[bid]["successors"]))
        incoming = uses[bid] | (outgoing - defs[bid])
        live_out[bid] = outgoing
        if incoming != live_in[bid]:
            live_in[bid] = incoming
            for predecessor in blocks[bid]["predecessors"]:
                if predecessor not in queued:
                    pending.append(predecessor)
                    queued.add(predecessor)
    # 5. Reachability is structural: no path from entry means no execution.
    reachable, pending = set(), [0]
    while pending:
        bid = pending.pop()
        if bid in reachable:
            continue
        reachable.add(bid)
        pending.extend(blocks[bid]["successors"])
    # 6. Reverse-scan next use within each block. Cross-block need is live-out only.
    for block in blocks:
        bid = block["id"]
        block.update({"use": sorted(uses[bid]), "def": sorted(defs[bid]), "live_in": sorted(live_in[bid]),
                      "live_out": sorted(live_out[bid]), "reachable": bid in reachable, "rows": []})
        next_use = {temp: None for temp in live_out[bid]}
        for n in reversed(range(block["start"], block["end"])):
            read, written = temp_access(code[n])
            block["rows"].append({"index": n, "uses": sorted(read), "defs": sorted(written),
                                  "next": [{"temp": temp, "at": next_use.get(temp), "live_out": temp in next_use and next_use[temp] is None}
                                           for temp in sorted(read | written)]})
            for temp in written:
                next_use.pop(temp, None)
            for temp in read:
                next_use[temp] = n
        block["rows"].reverse()
    return {"id": fn["id"], "name": fn["name"], "blocks": blocks, "edges": edges,
            "worklist_visits": updates}

polyglot/artifact.py:
"""Versioned JSON loader with operand and control-flow stack validation."""

import json
import math
from collections import deque
from .types import VALUE_TYPES, is_value_type, MAX_ARRAY_LENGTH
from .formats import FORMAT_TYPES

UNARY = {"+", "-", "not", "float"}
BINARY = {"+", "-", "*", "/", "%", "==", "!=", "<", "<=", ">", ">=", "and", "or"}


class ArtifactError(ValueError):
    pass


def validate(artifact: dict) -> dict:
    def require(condition, message):
        if not condition:
            raise ArtifactError(message)

    def index(value, size):
        return type(value) is int and 0 <= value < size

    require(type(artifact) is dict, "Artifact must be an object.")
    require(artifact.get("format") == "polyglot-bytecode" and type(artifact.get("version")) is int
            and artifact["version"] in (1, 2, 3), "Unsupported artifact format/version.")
    version = artifact["version"]
    constants, functions = artifact.get("constants"), artifact.get("functions")
    require(type(constants) is list and len(constants) <= 100000 and type(functions) is list
            and 0 < len(functions) <= 1000, "Invalid constant/function tables.")
    require(type(artifact.get("global_count")) is int and 0 <= artifact["global_count"] <= 100000,
            "Invalid global storage count.")
    require(index(artifact.get("entry"), len(functions)), "Invalid entry function.")
    for constant in constants:
        require(type(constant) is dict, "Invalid constant.")
        require(type(constant.get("type")) is str, "Invalid constant type.")
        expected = {"int": int, "float": float, "bool": bool, "string": str}.get(constant["type"])
        require(expected is not None and type(constant.get("value")) is expected, "Invalid constant type/value.")
        if expected is float:
            require(math.isfinite(constant["value"]), "Nonfinite constant.")
    for fid, fn in enumerate(functions):
        require(type(fn) is dict and type(fn.get("id")) is int and fn["id"] == fid
                and type(fn.get("name")) is str, "Invalid function identity.")
        locals_count = fn.get("local_count")
        require(type(locals_count) is int and 0 <= locals_count <= 100000, "Invalid local storage count.")
        valid_type = is_value_type if version >= 2 else lambda t: t in VALUE_TYPES
        require(type(fn.get("params")) is list and all(valid_type(t) for t in fn["params"])
                and len(fn["params"]) <= locals_count, "Invalid function parameters.")
        require(fn.get("return_type") == "void" or valid_type(fn.get("return_type")), "Invalid return type.")
        require(type(fn.get("code")) is list and 0 < len(fn["code"]) <= 100000, "Invalid instruction table.")
    require(functions[artifact["entry"]]["params"] == []
            and functions[artifact["entry"]]["return_type"] == "void", "Entry must be a parameterless void function.")
    for fn in functions:
        code = fn["code"]
        for instruction in code:
            require(type(instruction) is dict and type(instruction.get("args")) is list, "Invalid instruction.")
            op, args, loc = instruction.get("op"), instruction["args"], instruction.get("source")
            require(type(op) is str, "Invalid opcode.")
            if op.startswith("ARRAY_"):
                require(version >= 2, "Array instructions require artifact version 2 or newer.")
            require(type(loc) is dict and type(loc.get("filename")) is str and type(loc.get("line")) is int
                    and type(loc.get("column")) is int and loc["line"] > 0 and loc["column"] > 0
                    and type(loc.get("excerpt", "")) is str, "Invalid source mapping.")
            if op in ("CONST", "LOAD_LOCAL", "STORE_LOCAL", "LOAD_GLOBAL", "STORE_GLOBAL"):
                bound = len(constants) if op == "CONST" else fn["local_count"] if op.endswith("LOCAL") else artifact["global_count"]
                require(len(args) == 1 and index(args[0], bound), "Invalid storage/constant operand.")
            elif op in ("UNARY", "BINARY"):
                require(len(args) == 1 and type(args[0]) is str
                        and args[0] in (UNARY if op == "UNARY" else BINARY), "Invalid operation.")
            elif op == "FORMAT":
                require(version >= 3 and len(args) == 1 and type(args[0]) is str and args[0] in FORMAT_TYPES,
                        "Invalid formatting instruction or artifact version.")
            elif op == "OUTPUT":
                require(len(args) == 3 and type(args[0]) is int and 0 <= args[0] <= 1000
                        and type(args[1]) is str and type(args[2]) is str, "Invalid output operands.")
            elif op in ("JUMP", "JUMP_IF_FALSE"):
                require(len(args) == 1 and index(args[0], len(code)), "Invalid jump target.")
            elif op == "CALL":
                require(len(args) == 2 and index(args[0], len(functions)) and type(args[1]) is int
                        and args[1] == len(functions[args[0]]["params"]), "Invalid function reference/arity.")
            elif op == "ARRAY_BUILD":
                require(len(args) == 2 and args[0] in VALUE_TYPES and type(args[1]) is int
                        and 0 <= args[1] <= MAX_ARRAY_LENGTH, "Invalid array construction operands.")
            elif op == "ARRAY_NEW":
                require(len(args) == 1 and args[0] in VALUE_TYPES, "Invalid array element type.")
            elif op in ("ARRAY_GET", "ARRAY_SET", "ARRAY_CHECK", "ARRAY_LENGTH", "ARRAY_SIZE_CHECK"):
                require(not args, "Invalid array instruction operands.")
            elif op in ("ASSERT", "TRAP"):
                require(len(args) == 2 and all(type(v) is str for v in args), "Invalid runtime guard.")
            elif op in ("RETURN_VOID", "RETURN_VALUE", "POP"):
                require(not args, "Invalid instruction operands.")
                if op == "RETURN_VOID":
                    require(fn["return_type"] == "void", "Void return in a value function.")
                elif op == "RETURN_VALUE":
                    require(fn["return_type"] != "void", "Value return in a void function.")
            else:
                raise ArtifactError(f"Unknown instruction {op!r}.")
        # One incoming stack height per reachable instruction; branches must agree.
        heights, work = {0: 0}, deque([0])
        while work:
            position = work.popleft()
            instruction = code[position]
            op, args, height = instruction["op"], instruction["args"], heights[position]
            consume = 0
            produce = 0
            if op in ("CONST", "LOAD_LOCAL", "LOAD_GLOBAL"):
                produce = 1
            elif op in ("STORE_LOCAL", "STORE_GLOBAL", "POP", "JUMP_IF_FALSE", "ASSERT", "RETURN_VALUE"):
                consume = 1
            elif op in ("UNARY", "FORMAT"):
                consume = produce = 1
            elif op == "BINARY":
                consume, produce = 2, 1
            elif op == "OUTPUT":
                consume = args[0]
            elif op == "CALL":
                consume = args[1]
                produce = int(functions[args[0]]["return_type"] != "void")
            elif op == "ARRAY_BUILD":
                consume, produce = args[1], 1
            elif op in ("ARRAY_NEW", "ARRAY_LENGTH"):
                consume = produce = 1
            elif op == "ARRAY_GET":
                consume, produce = 2, 1
            elif op in ("ARRAY_CHECK", "ARRAY_SIZE_CHECK"):
                consume = 2
            elif op == "ARRAY_SET":
                consume = 3
            require(height >= consume, "Operand stack underflow.")
            new_height = height - consume + produce
            require(new_height <= 4096, "Operand stack exceeds its limit.")
            if op in ("RETURN_VOID", "RETURN_VALUE", "TRAP"):
                require(op == "TRAP" or new_height == 0, "Return leaves values on the operand stack.")
                continue
            targets = [args[0]] if op == "JUMP" else [position + 1, args[0]] if op == "JUMP_IF_FALSE" else [position + 1]
            for target in targets:
                require(target < len(code), "Function can fall off the instruction table.")
                if target in heights:
                    require(heights[target] == new_height, "Inconsistent operand stack at branch merge.")
                else:
                    heights[target] = new_height
                    work.append(target)
    return artifact


def dumps(artifact: dict) -> str:
    validate(artifact)
    chunks, size = [], 0
    encoder = json.JSONEncoder(indent=2, ensure_ascii=False, allow_nan=False)
    for chunk in encoder.iterencode(artifact):
        size += len(chunk.encode("utf-8"))
        if size > 5_000_000:
            raise ArtifactError("Artifact exceeds the 5 MB limit.")
        chunks.append(chunk)
    return "".join(chunks)


def loads(text: str) -> dict:
    if len(text.encode("utf-8")) > 5_000_000:
        raise ArtifactError("Artifact exceeds the 5 MB limit.")
    def pairs(items):
        result = {}
        for name, value in items:
            if name in result:
                raise ArtifactError(f"Duplicate JSON key {name!r}.")
            result[name] = value
        return result
    try:
        value = json.loads(text, object_pairs_hook=pairs)
        return validate(value)
    except (ValueError, TypeError, KeyError, RecursionError) as exc:
        raise ArtifactError(f"Invalid bytecode artifact: {exc}") from exc

polyglot/codegen.py:
"""Translate three-address IR into independent stack bytecode."""

from .ir import IRFunction


def generate(functions: list[IRFunction], symbols: list[dict]) -> dict:
    constants, compiled = [], []
    for fn in functions:
        code, labels, jumps = [], {}, []

        def emit(op, args, location):
            code.append({"op": op, "args": args, "source": location})

        def load(temp, location):
            emit("LOAD_LOCAL", [fn.local_count + temp], location)

        def store(temp, location):
            emit("STORE_LOCAL", [fn.local_count + temp], location)

        def jump(op, target, loc):
            jumps.append((len(code), target))
            emit(op, [0], loc)

        for inst in fn.instructions:
            op, loc = inst["op"], inst["source"]
            if op == "LABEL":
                labels[inst["label"]] = len(code)
            elif op == "CONST":
                constants.append({"type": inst["type"], "value": inst["value"]})
                emit("CONST", [len(constants) - 1], loc)
                store(inst["dest"], loc)
            elif op == "LOAD":
                emit("LOAD_" + inst["storage"].upper(), [inst["slot"]], loc)
                store(inst["dest"], loc)
            elif op == "STORE":
                load(inst["value"], loc)
                emit("STORE_" + inst["storage"].upper(), [inst["slot"]], loc)
            elif op == "MOVE":
                load(inst["value"], loc)
                store(inst["dest"], loc)
            elif op in ("UNARY", "WIDEN"):
                load(inst["value"], loc)
                emit("UNARY", [inst.get("operator", "float")], loc)
                store(inst["dest"], loc)
            elif op == "BINARY":
                load(inst["left"], loc)
                load(inst["right"], loc)
                emit("BINARY", [inst["operator"]], loc)
                store(inst["dest"], loc)
            elif op == "FORMAT":
                load(inst["value"], loc)
                emit("FORMAT", [inst["specifier"]], loc)
                store(inst["dest"], loc)
            elif op == "ARRAY_BUILD":
                for value in inst["args"]:
                    load(value, loc)
                emit("ARRAY_BUILD", [inst["element_type"], len(inst["args"])], loc)
                store(inst["dest"], loc)
            elif op == "ARRAY_NEW":
                load(inst["size"], loc)
                emit("ARRAY_NEW", [inst["element_type"]], loc)
                store(inst["dest"], loc)
            elif op in ("ARRAY_GET", "ARRAY_SET", "ARRAY_CHECK"):
                load(inst["array"], loc)
                load(inst["index"], loc)
                if op == "ARRAY_SET":
                    load(inst["value"], loc)
                emit(op, [], loc)
                if op == "ARRAY_GET":
                    store(inst["dest"], loc)
            elif op == "ARRAY_LENGTH":
                load(inst["array"], loc)
                emit(op, [], loc)
                store(inst["dest"], loc)
            elif op == "ARRAY_SIZE_CHECK":
                load(inst["array"], loc)
                load(inst["size"], loc)
                emit(op, [], loc)
            elif op == "OUTPUT":
                for value in inst["args"]:
                    load(value, loc)
                emit("OUTPUT", [len(inst["args"]), inst["separator"], inst["ending"]], loc)
            elif op == "BRANCH":
                load(inst["condition"], loc)
                jump("JUMP_IF_FALSE", inst["false"], loc)
                jump("JUMP", inst["true"], loc)
            elif op == "JUMP":
                jump("JUMP", inst["target"], loc)
            elif op == "CALL":
                for arg in inst["args"]:
                    load(arg, loc)
                emit("CALL", [inst["function"], len(inst["args"])], loc)
                if inst["dest"] is not None:
                    store(inst["dest"], loc)
            elif op == "RETURN_VALUE":
                load(inst["value"], loc)
                emit("RETURN_VALUE", [], loc)
            elif op == "RETURN_VOID":
                emit("RETURN_VOID", [], loc)
            elif op == "ASSERT":
                load(inst["condition"], loc)
                emit("ASSERT", [inst["code"], inst["message"]], loc)
            elif op == "TRAP":
                emit("TRAP", [inst["code"], inst["message"]], loc)
            else:
                raise ValueError(f"Unknown IR operation {op}")
        for position, target in jumps:
            code[position]["args"][0] = labels[target]
        compiled.append({"id": fn.id, "name": fn.name, "params": fn.params, "return_type": fn.return_type,
                         "local_count": fn.local_count + fn.temp_count, "code": code})
    return {"format": "polyglot-bytecode", "version": 3, "entry": 0, "constants": constants,
            "global_count": sum(s["storage"] == "global" for s in symbols), "functions": compiled}

polyglot/compiler.py:
"""The single compiler API used by the CLI and browser worker."""

from dataclasses import asdict, is_dataclass
from .source import Source
from .lexer import lex
from .parser import Parser
from .semantics import Analyzer
from .ir import Lowerer
from .codegen import generate
from .artifact import dumps, ArtifactError
from .diagnostics import PolyglotError, Diagnostic
from .optimizer import optimize_functions


def serializable(value):
    if is_dataclass(value):
        return serializable(asdict(value))
    if isinstance(value, dict):
        return {k: serializable(v) for k, v in value.items()}
    if isinstance(value, list):
        return [serializable(v) for v in value]
    return value


def compile_source(text: str, filename: str = "program.poly", *, optimize: bool = True) -> dict:
    if type(optimize) is not bool:
        raise ValueError("optimize must be a Boolean")
    source = Source(text, filename)
    stages = {}
    try:
        if len(text.encode("utf-8")) > 131072:
            raise PolyglotError(Diagnostic("C001", "Source exceeds the 128 KiB limit.", source.location(source.span(0, 0))))
        tokens = lex(source)
        stages["tokens"] = serializable(tokens)
        parser = Parser(source, tokens)
        tree = parser.parse()
        stages["recognition"] = serializable(parser.recognition)
        stages["layout"] = serializable(parser.layout.events)
        stages["ast"] = serializable(tree)
        analyzer = Analyzer(source)
        symbols = analyzer.analyze(tree)
        stages["symbols"] = symbols
        stages["ast"] = serializable(tree)
        functions = Lowerer(source, analyzer).lower(tree)
        stages["ir"] = serializable(functions)
        if optimize:
            functions, stages["optimization"] = optimize_functions(functions)
        else:
            stages["optimization"] = {"enabled": False, "functions": [], "passes": []}
        stages["optimized_ir"] = serializable(functions)
        artifact = generate(functions, symbols)
        dumps(artifact)
        stages["bytecode"] = artifact
        return {"ok": True, "diagnostics": [], "stages": stages, "artifact": artifact}
    except PolyglotError as exc:
        return {"ok": False, "diagnostics": [asdict(exc.diagnostic)], "stages": stages, "artifact": None}
    except RecursionError:
        return {"ok": False, "diagnostics": [asdict(Diagnostic("P099", "Expression nesting limit exceeded.", source.location(source.span(0, 0))))],
                "stages": stages, "artifact": None}
    except ArtifactError as exc:
        return {"ok": False, "diagnostics": [asdict(Diagnostic("C002", str(exc), source.location(source.span(0, 0))))],
                "stages": stages, "artifact": None}

polyglot/formats.py:
"""Compile literal printf formats into a small, explicit formatting plan."""

FORMAT_TYPES = {"d": "int", "f": "float", "s": "string"}


class FormatError(ValueError):
    pass


def parse_format(text: str) -> tuple[list[dict], list[str]]:
    segments, types, literal = [], [], []
    position = 0
    while position < len(text):
        character = text[position]
        position += 1
        if character != "%":
            literal.append(character)
            continue
        if position == len(text):
            raise FormatError("Trailing '%' in printf format.")
        specifier = text[position]
        position += 1
        if specifier == "%":
            literal.append("%")
            continue
        if specifier not in FORMAT_TYPES:
            raise FormatError(f"Unsupported printf format %{specifier}.")
        if literal:
            segments.append({"kind": "literal", "text": "".join(literal)})
            literal = []
        segments.append({"kind": "value", "specifier": specifier, "index": len(types)})
        types.append(FORMAT_TYPES[specifier])
    if literal:
        segments.append({"kind": "literal", "text": "".join(literal)})
    return segments, types

polyglot/layout.py:
"""Parser-driven block context: only Python suites activate indentation."""

from dataclasses import dataclass
from .lexer import Token
from .source import Source
from .diagnostics import fail


@dataclass
class Context:
    style: str
    column: int


class Layout:
    def __init__(self, source: Source):
        self.source = source
        self.stack: list[Context] = []
        self.events: list[dict] = []

    def enter(self, style: str, token: Token) -> None:
        if len(self.stack) >= 100:
            fail(self.source, token.span, "P099", "Block nesting limit exceeded.")
        self.stack.append(Context(style, token.span.column))
        self.events.append({"kind": "INDENT" if style == "indent" else "BRACE_OPEN", "span": token.span})

    def leave(self, token: Token) -> None:
        context = self.stack.pop()
        self.events.append({"kind": "DEDENT" if context.style == "indent" else "BRACE_CLOSE", "span": token.span})

polyglot/lexer.py:
"""Character lexer. Braces do not suppress logical newlines; parentheses do."""

from dataclasses import dataclass
from .source import Source, Span
from .diagnostics import fail


@dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    span: Span


def lex(source: Source) -> list[Token]:
    text = source.text.replace("\r\n", "\n")
    if text != source.text:
        source.__init__(text, source.filename)
    tokens: list[Token] = []
    i = 0
    parens: list[int] = []
    leading = True

    def emit(kind: str, start: int, end: int, value: object = None) -> None:
        tokens.append(Token(kind, text[start:end], value, source.span(start, end)))

    def newline(pos: int) -> None:
        if not parens and (not tokens or tokens[-1].kind != "NEWLINE"):
            emit("NEWLINE", pos, min(pos + 1, len(text)))

    while i < len(text):
        c = text[i]
        if c in " \t":
            if c == "\t" and leading:
                fail(source, source.span(i, i + 1), "L001", "Tabs in indentation are unsupported.",
                     "Use spaces for indentation.")
            i += 1
            continue
        if c == "\n":
            newline(i)
            leading = True
            i += 1
            continue
        if c == "#" or text.startswith("//", i):
            while i < len(text) and text[i] != "\n":
                i += 1
            continue
        if text.startswith("/*", i):
            start = i
            end = text.find("*/", i + 2)
            if end < 0:
                fail(source, source.span(start, start + 2), "L002", "Unclosed block comment.")
            for p in range(i, end + 2):
                if text[p] == "\n":
                    newline(p)
                    leading = True
            i = end + 2
            continue
        leading = False
        start = i
        if c in "\"'":
            quote = c
            if text.startswith(c * 3, i):
                fail(source, source.span(i, i + 3), "L003", "Triple-quoted strings are unsupported.")
            i += 1
            value = ""
            escapes = {"n": "\n", "r": "\r", "t": "\t", "\\": "\\", "'": "'", '"': '"'}
            while i < len(text) and text[i] != quote:
                if text[i] == "\n":
                    fail(source, source.span(start, i), "L004", "Unclosed string literal.")
                if text[i] == "\\":
                    i += 1
                    if i >= len(text) or text[i] not in escapes:
                        fail(source, source.span(i - 1, min(i + 1, len(text))), "L005", "Unsupported string escape.")
                    value += escapes[text[i]]
                else:
                    value += text[i]
                i += 1
            if i >= len(text):
                fail(source, source.span(start, i), "L004", "Unclosed string literal.")
            i += 1
            emit("STRING", start, i, value)
        elif c.isascii() and (c.isalpha() or c == "_"):
            i += 1
            while i < len(text) and text[i].isascii() and (text[i].isalnum() or text[i] == "_"):
                i += 1
            emit("NAME", start, i, text[start:i])
        elif c.isascii() and c.isdigit():
            i += 1
            while i < len(text) and text[i].isascii() and text[i].isdigit():
                i += 1
            floating = False
            if i < len(text) and text[i] == "." and i + 1 < len(text) and text[i + 1].isdigit():
                floating = True
                i += 1
                while i < len(text) and text[i].isascii() and text[i].isdigit():
                    i += 1
            if i < len(text) and text[i] in "eE":
                floating = True
                i += 1
                if i < len(text) and text[i] in "+-":
                    i += 1
                exponent = i
                while i < len(text) and text[i].isascii() and text[i].isdigit():
                    i += 1
                if i == exponent:
                    fail(source, source.span(start, i), "L006", "Invalid numeric exponent.")
            spelling = text[start:i]
            try:
                value = float(spelling) if floating else int(spelling)
            except ValueError:
                fail(source, source.span(start, i), "L006", "Numeric literal is too large or invalid.")
            emit("NUMBER", start, i, value)
        else:
            op = next((p for p in ("::", "<<", "->", "+=", "-=", "++", "--", "==", "!=", "<=", ">=", "&&", "||")
                       if text.startswith(p, i)), None)
            if op:
                i += len(op)
            elif c in "()[]{}:;,+-*/%<>=!.":
                op = c
                i += 1
            else:
                fail(source, source.span(i, i + 1), "L007", f"Invalid token {c!r}.")
            if op in ("(", "["):
                parens.append(start)
            elif op in (")", "]"):
                if not parens or text[parens[-1]] != ("(" if op == ")" else "["):
                    fail(source, source.span(start, i), "L008", "Unexpected or mismatched closing delimiter.")
                parens.pop()
            emit("OP", start, i)
    if parens:
        fail(source, source.span(parens[-1], parens[-1] + 1), "L008", "Unclosed parenthesis or array bracket.")
    if not tokens or tokens[-1].kind != "NEWLINE":
        emit("NEWLINE", len(text), len(text))
    emit("EOF", len(text), len(text))
    return tokens

polyglot/optimizer.py:
"""Conservative local IR optimization before stack-bytecode generation.

Only proven primitive constants are folded. Operations that can raise a runtime
error are retained unless their exact successful result is known. Calls, stores,
loads, array operations and output are never removed as dead pure expressions.
"""

import copy
import math
from dataclasses import asdict
from .analysis import analyze_function

UNKNOWN = object()


def safe_constant(value, expected: str) -> bool:
    actual = {bool: "bool", int: "int", float: "float", str: "string"}.get(type(value))
    if actual != expected:
        return False
    if type(value) is int:
        return value.bit_length() <= 1_000_000
    if type(value) is float:
        return math.isfinite(value)
    if type(value) is str:
        return len(value.encode("utf-8")) <= 131072
    return True


def constant_result(instruction: dict, constants: dict):
    op = instruction["op"]
    value = constants.get(instruction.get("value"), UNKNOWN)
    try:
        if op == "MOVE":
            return value
        if op in ("UNARY", "WIDEN") and value is not UNKNOWN:
            operator = instruction.get("operator", "float")
            if operator == "float":
                return float(value)
            if operator == "not":
                return not value
            if operator == "-":
                return -value
            if operator == "+":
                return +value
        if op != "BINARY":
            return UNKNOWN
        left = constants.get(instruction["left"], UNKNOWN)
        right = constants.get(instruction["right"], UNKNOWN)
        if left is UNKNOWN or right is UNKNOWN:
            return UNKNOWN
        operator = instruction["operator"]
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            return left / right
        if operator == "%":
            # Match the VM's truncation-toward-zero remainder, including negatives.
            if type(left) is type(right) is int:
                return (abs(left) % abs(right)) * (-1 if left < 0 else 1)
            return math.fmod(left, right)
        if operator == "==":
            return left == right
        if operator == "!=":
            return left != right
        if operator == "<":
            return left < right
        if operator == "<=":
            return left <= right
        if operator == ">":
            return left > right
        if operator == ">=":
            return left >= right
        if operator == "and":
            return left and right
        if operator == "or":
            return left or right
    except (ZeroDivisionError, OverflowError, ValueError, TypeError):
        # Preserve the original runtime operation, diagnostic and source location.
        pass
    return UNKNOWN


def optimize_functions(functions: list) -> tuple[list, dict]:
    optimized, reports = [], []
    budget = 3000
    for index, original in enumerate(functions):
        fn = copy.deepcopy(original)
        before = len(fn.instructions)
        report = {"id": fn.id, "name": fn.name, "before": before, "after": before,
                  "constant_folds": 0, "constant_branches": 0, "unreachable_removed": 0, "dead_constants_removed": 0}
        reports.append(report)
        optimized.append(fn)
        # Bounded analysis avoids making large valid programs harder to compile.
        if index >= 12 or before > 1500 or before > budget:
            report["skipped"] = "Optimization analysis limit reached. Original IR retained."
            continue
        cfg = analyze_function(asdict(fn))
        if "omitted" in cfg:
            report["skipped"] = cfg["omitted"]
            continue
        budget -= before

        # Constants are local to a basic block. No facts are propagated through
        # mutable storage, calls or control-flow joins.
        folded = []
        for block in cfg["blocks"]:
            constants = {}
            for original_instruction in fn.instructions[block["start"]:block["end"]]:
                instruction = copy.deepcopy(original_instruction)
                op = instruction["op"]
                result = constant_result(instruction, constants)
                if result is not UNKNOWN and safe_constant(result, instruction.get("type", "")):
                    instruction = {"op": "CONST", "dest": instruction["dest"], "value": result,
                                   "type": instruction["type"], "source": instruction["source"]}
                    report["constant_folds"] += 1
                elif op == "BRANCH" and type(constants.get(instruction["condition"])) is bool:
                    target = instruction["true"] if constants[instruction["condition"]] else instruction["false"]
                    instruction = {"op": "JUMP", "target": target, "source": instruction["source"]}
                    report["constant_branches"] += 1
                dest = instruction.get("dest")
                if dest is not None:
                    constants.pop(dest, None)
                    if instruction["op"] == "CONST" and safe_constant(instruction["value"], instruction["type"]):
                        constants[dest] = instruction["value"]
                folded.append(instruction)
        fn.instructions = folded

        # Rebuild the graph after branch simplification, then remove only blocks
        # that have no path from this function's entry.
        cfg = analyze_function(asdict(fn))
        reachable = []
        for block in cfg["blocks"]:
            instructions = fn.instructions[block["start"]:block["end"]]
            if block["reachable"]:
                reachable.extend(instructions)
            else:
                report["unreachable_removed"] += len(instructions)
        fn.instructions = reachable

        # Next-use facts are seeded by cross-block liveness. Removing a CONST
        # removes no operand uses, so no additional dead-use iteration is needed.
        # Never discard a LOAD, division, call, array check or other trapping op.
        cfg = analyze_function(asdict(fn))
        retained = []
        for block in cfg["blocks"]:
            for row in block["rows"]:
                instruction = fn.instructions[row["index"]]
                needed = any(n["at"] is not None or n["live_out"] for n in row["next"])
                if (instruction["op"] == "CONST" and not needed
                        and safe_constant(instruction["value"], instruction["type"])):
                    report["dead_constants_removed"] += 1
                    continue
                retained.append(instruction)
        fn.instructions = retained
        report["after"] = len(retained)
    return optimized, {"enabled": True, "functions": reports,
                       "passes": ["local constant folding", "constant branch simplification", "unreachable basic-block removal", "liveness and next-use dead constant removal"],
                       "limits": {"functions": 12, "instructions_per_function": 1500, "total_instructions": 3000, "blocks_per_function": 120}}

polyglot/parser/basic_family.py:
"""Restricted BASIC spellings normalize to shared assignments and output."""

from ..ast import Node
from .shared import expression


def statement(p):
    start = p.take()
    if start.text == "LET":
        node = p.assignment()
        if node.data["op"] != "=":
            p.error(start, "P030", "BASIC LET requires '=' assignment.")
        node.span = p.join(start.span, node.span)
        p.end()
        return p.record(node, "BASIC", "let-assignment", ["explicit uppercase LET prefix"])
    args = [] if p.at("NEWLINE") or p.at(";") else [expression(p)]
    node = Node("Output", p.join(start.span, p.previous().span), {"args": args, "separator": "", "ending": "\n"})
    p.end()
    return p.record(node, "BASIC", "basic-print", ["explicit uppercase PRINT builtin"])

polyglot/parser/c_family.py:
"""Shared C++/Java grammar, with explicit built-in output forms."""

from ..ast import Node
from .shared import TYPES, expression, type_spec, array_literal


def declaration(p):
    start = p.peek()
    declared_type = type_spec(p)
    name = p.expect("NAME")
    size = None
    if p.match("["):
        if declared_type.endswith("[]"):
            p.error(name, "P025", "Multidimensional arrays are unsupported.")
        declared_type += "[]"
        size = None if p.at("]") else expression(p)
        p.expect("]")
        if p.at("["):
            p.error(name, "P025", "Multidimensional arrays are unsupported.")
    if p.at("{"):
        p.error(name, "P022", "A function declaration needs a name followed by parameters.", "Use int name(int parameter) { ... }.")
    value = None
    if p.match("="):
        value = array_literal(p, "{", "}") if p.at("{") else expression(p)
    elif size is not None:
        value = Node("ArrayNew", size.span, {"element_type": declared_type[:-2], "size": size})
        size = None
    return Node("Declare", p.join(start.span, p.previous().span),
                {"name": name.text, "type": declared_type, "value": value, "size": size})


def function(p):
    start = p.peek()
    return_type = type_spec(p)
    name = p.expect("NAME")
    p.expect("(")
    params = []
    if not p.at(")"):
        while True:
            parameter_type = type_spec(p)
            parameter = p.expect("NAME")
            if p.match("["):
                if parameter_type.endswith("[]"):
                    p.error(parameter, "P025", "Multidimensional arrays are unsupported.")
                p.expect("]")
                parameter_type += "[]"
            params.append({"name": parameter.text, "type": parameter_type, "span": parameter.span})
            if not p.match(","):
                break
    p.expect(")")
    if not p.at("{"):
        p.error(p.peek(), "P001", "Typed functions require a brace body.")
    body = p.suite(start)
    node = Node("Function", p.join(start.span, body.span), {"name": name.text, "params": params,
                                                          "return_type": return_type, "body": body})
    return p.record(node, "shared-c", "typed-function", ["typed signature and braces"])


def javascript_declaration(p):
    start = p.take()
    name = p.expect("NAME")
    if not p.match("="):
        p.error(p.peek(), "P030", "let and const declarations require an initializer.")
    value = expression(p)
    node = Node("Declare", p.join(start.span, value.span),
                {"name": name.text, "type": None, "value": value, "mutable": start.text == "let"})
    return p.record(node, "JavaScript", "js-declaration", [f"explicit {start.text} declaration"])


def javascript_function(p):
    start = p.expect("function")
    name = p.expect("NAME")
    p.expect("(")
    params = []
    if not p.at(")"):
        while True:
            parameter = p.expect("NAME")
            if not p.match(":"):
                p.error(p.peek(), "P020", "Function parameters require Polyglot type annotations.")
            params.append({"name": parameter.text, "type": type_spec(p), "span": parameter.span})
            if not p.match(","):
                break
    p.expect(")")
    if not p.match(":"):
        p.error(p.peek(), "P020", "JavaScript-style functions require a return annotation.", "Use function name(...): int { ... } or another supported return type.")
    return_type = type_spec(p)
    if not p.at("{"):
        p.error(p.peek(), "P001", "JavaScript-style functions require a brace body.")
    body = p.suite(start)
    node = Node("Function", p.join(start.span, body.span),
                {"name": name.text, "params": params, "return_type": return_type, "body": body})
    return p.record(node, "JavaScript", "js-annotated-function", ["function keyword, explicit annotations and braces"])


def javascript_output(p):
    start = p.expect("console")
    p.expect(".")
    p.expect("log")
    args = p.arguments()
    node = Node("Output", p.join(start.span, p.previous().span),
                {"args": args, "separator": " " if len(args) > 1 else "", "ending": "\n"})
    p.end(True)
    return p.record(node, "JavaScript", "console-log", ["recognized console.log builtin"])


def formatted_output(p):
    start = p.expect("printf")
    args = p.arguments()
    if not args:
        p.error(start, "P030", "printf requires a literal format string.")
    node = Node("Printf", p.join(start.span, p.previous().span), {"format": args[0], "args": args[1:]})
    p.end(True)
    return p.record(node, "C", "printf", ["recognized restricted printf builtin"])


def for_loop(p):
    start = p.expect("for")
    p.expect("(")
    initial = None
    if not p.at(";"):
        if p.peek().text in TYPES:
            initial = declaration(p)
        elif p.peek().text in ("let", "const"):
            initial = javascript_declaration(p)
        else:
            initial = p.assignment()
    p.expect(";")
    condition = expression(p) if not p.at(";") else Node("Literal", p.peek().span, {"value": True})
    p.expect(";")
    update = p.assignment() if not p.at(")") else None
    p.expect(")")
    if not p.at("{"):
        p.error(p.peek(), "P001", "Three-part loops require a brace body.")
    body = p.suite(start)
    node = Node("For", p.join(start.span, body.span), {"initial": initial, "condition": condition, "update": update, "body": body})
    if initial is not None and initial.meta.get("syntax", {}).get("family") == "JavaScript":
        return p.record(node, "JavaScript", "js-three-part-for", ["let/const initializer and brace loop"])
    return p.record(node, "shared-c", "three-part-for", ["semicolon-separated header and braces"])


def output(p):
    start = p.take()
    if start.text == "System":
        for part in (".", "out", ".", "println"):
            p.expect(part)
        args = p.arguments()
        if len(args) != 1:
            p.error(start, "P023", "System.out.println requires exactly one argument.")
        node = Node("Output", p.join(start.span, p.previous().span), {"args": args, "separator": "", "ending": "\n"})
        p.end(True)
        return p.record(node, "Java", "println", ["recognized System.out.println builtin"])
    if start.text == "std":
        p.expect("::")
        p.expect("cout")
    pieces = []
    if not p.at("<<"):
        p.error(p.peek(), "P023", "cout requires an insertion chain.")
    while p.match("<<"):
        item = p.peek()
        if item.text == "endl" or (item.text == "std" and p.peek(1).text == "::" and p.peek(2).text == "endl"):
            if p.match("std"):
                p.expect("::")
            p.expect("endl")
            if pieces:
                pieces[-1].data["ending"] += "\n"
            else:
                pieces.append(Node("Output", item.span, {"args": [], "separator": "", "ending": "\n"}))
        else:
            value = expression(p)
            pieces.append(Node("Output", value.span, {"args": [value], "separator": "", "ending": ""}))
    node = pieces[0] if len(pieces) == 1 else Node("OutputSequence", start.span, {"body": pieces})
    node.span = p.join(start.span, p.previous().span)
    p.end(True)
    return p.record(node, "C++", "cout-chain", ["recognized cout insertion builtin"])

polyglot/parser/dispatch.py:
"""Deterministic construct dispatch, plus structural suite parsing."""

from ..ast import Node
from ..source import Source, Span
from ..diagnostics import fail
from ..layout import Layout
from .shared import TYPES, expression
from . import python_family, c_family, basic_family


class Parser:
    def __init__(self, source: Source, tokens: list):
        self.source, self.tokens, self.pos = source, tokens, 0
        self.layout = Layout(source)
        self.recognition: list[dict] = []

    def peek(self, offset: int = 0):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def previous(self):
        return self.tokens[self.pos - 1]

    def take(self):
        token = self.peek()
        self.pos += 1
        return token

    def at(self, spelling: str) -> bool:
        return self.peek().text == spelling or self.peek().kind == spelling

    def match(self, spelling: str) -> bool:
        if self.at(spelling):
            self.take()
            return True
        return False

    def expect(self, spelling: str):
        if not self.at(spelling):
            self.error(self.peek(), "P001", f"Expected {spelling!r}, found {self.peek().text or self.peek().kind!r}.")
        return self.take()

    def error(self, token, code: str, message: str, suggestion: str = "") -> None:
        fail(self.source, token.span, code, message, suggestion)

    def join(self, a: Span, b: Span) -> Span:
        return self.source.span(a.start, b.end)

    def newlines(self):
        while self.match("NEWLINE"):
            pass

    def end(self, required_semicolon: bool = False):
        if self.match(";"):
            self.newlines()
        elif not required_semicolon and self.match("NEWLINE"):
            self.newlines()
        else:
            self.error(self.peek(), "P002", "Missing semicolon." if required_semicolon else "Expected a statement terminator.")

    def arguments(self) -> list[Node]:
        self.expect("(")
        args = []
        if not self.at(")"):
            args.append(expression(self))
            while self.match(","):
                args.append(expression(self))
        if len(args) > 1000:
            self.error(self.peek(), "P024", "Argument count exceeds the 1000-argument resource limit.")
        self.expect(")")
        return args

    def record(self, node: Node, family: str, rule: str, reasons: list[str]):
        candidates = ["C", "C++", "Java"] if family == "shared-c" else []
        if family == "shared-c" and (rule in ("if", "while") or
                rule == "three-part-for" and (node.data["initial"] is None or node.data["initial"].kind in ("Assign", "IndexAssign"))):
            candidates.append("JavaScript")
        meta = {"family": family, "candidates": candidates,
                "grammar_rule": rule, "distinctive": family not in ("shared", "shared-c"), "reasons": reasons}
        node.meta["syntax"] = meta
        self.recognition.append({**meta, "kind": node.kind, "span": node.span})
        return node

    def parse(self) -> Node:
        self.newlines()
        statements = []
        while not self.at("EOF"):
            if self.peek().span.column != 1:
                self.error(self.peek(), "P003", "Unexpected top-level indentation.")
            statements.append(self.statement())
            self.newlines()
        return Node("Program", self.source.span(0, len(self.source.text)), {"body": statements})

    def suite(self, header) -> Node:
        opening = self.peek()
        body = []
        if self.match(":"):
            self.expect("NEWLINE")
            self.newlines()
            first = self.peek()
            if first.kind == "EOF" or first.text == "}" or first.span.column <= header.span.column:
                self.error(first, "P003", "Expected an indented suite.", "Indent the body using spaces.")
            column = first.span.column
            self.layout.enter("indent", first)
            while not self.at("EOF") and not self.at("}") and self.peek().span.column > header.span.column:
                if self.peek().span.column != column:
                    self.error(self.peek(), "P003", "Inconsistent suite indentation.")
                body.append(self.statement())
                self.newlines()
            self.layout.leave(self.peek())
            style = "indent"
        elif self.match("{"):
            self.layout.enter("brace", opening)
            self.newlines()
            while not self.at("}"):
                if self.at("EOF"):
                    self.error(opening, "P005", "Unclosed brace block.", "Add a closing '}'.")
                body.append(self.statement())
                self.newlines()
            closing = self.take()
            self.layout.leave(closing)
            self.newlines()
            style = "brace"
        else:
            self.error(opening, "P005", "Expected ':' and indentation, or a brace block.")
        node = Node("Block", self.join(opening.span, self.previous().span), {"body": body, "style": style})
        return node

    def assignment(self) -> Node:
        start = self.expect("NAME")
        target = None
        if self.match("["):
            index = expression(self)
            end = self.expect("]")
            target = Node("Index", self.join(start.span, end.span),
                          {"array": Node("Name", start.span, {"name": start.text}), "index": index})
        op = self.take()
        if op.text in ("++", "--"):
            if target is not None:
                self.error(op, "P025", "Indexed increment/decrement is unsupported; use += or -=.")
            value = Node("Literal", op.span, {"value": 1})
            operator = "+=" if op.text == "++" else "-="
        elif op.text in ("=", "+=", "-="):
            value, operator = expression(self), op.text
        else:
            self.error(op, "P006", "Expected an assignment or loop update.")
        if target is not None:
            return Node("IndexAssign", self.join(start.span, value.span), {"target": target, "op": operator, "value": value})
        return Node("Assign", self.join(start.span, value.span), {"name": start.text, "op": operator, "value": value})

    def control(self) -> Node:
        start = self.take()
        condition_start = self.pos
        parenthesized = self.at("(")
        condition = expression(self)
        if self.at("{"):
            depth, closing = 0, -1
            for index in range(condition_start, self.pos):
                text = self.tokens[index].text
                if text == "(":
                    depth += 1
                elif text == ")":
                    depth -= 1
                    if depth == 0:
                        closing = index
                        break
            if not parenthesized or closing != self.pos - 1:
                self.error(self.peek(), "P006", "Brace-style conditions require enclosing parentheses.")
        body = self.suite(start)
        family = "Python" if body.data["style"] == "indent" else "shared-c"
        if start.text == "while":
            node = Node("While", self.join(start.span, body.span), {"condition": condition, "body": body})
        else:
            branches = [{"condition": condition, "body": body}]
            otherwise = None
            while self.peek().text in ("elif", "else"):
                if family == "Python" and self.peek().span.column != start.span.column:
                    break
                branch = self.take()
                if branch.text == "elif" or self.match("if"):
                    next_condition = expression(self)
                    next_body = self.suite(branch)
                    branches.append({"condition": next_condition, "body": next_body})
                else:
                    otherwise = self.suite(branch)
                    break
            node = Node("If", self.join(start.span, self.previous().span), {"branches": branches, "else": otherwise})
        return self.record(node, family, start.text, ["indentation suite" if family == "Python" else "parenthesized condition and braces"])

    def statement(self) -> Node:
        token = self.peek()
        if token.text in ("class", "import", "from", "using", "namespace", "GOTO", "LABEL", "IF", "THEN", "END"):
            self.error(token, "P004", f"Unsupported construct {token.text!r}.", "Use the documented syntax subset.")
        if token.text in ("let", "const"):
            node = c_family.javascript_declaration(self)
            self.end(True)
            return node
        if token.text == "function":
            return c_family.javascript_function(self)
        if token.text == "console":
            return c_family.javascript_output(self)
        if token.text == "printf":
            return c_family.formatted_output(self)
        if token.text in ("LET", "PRINT"):
            return basic_family.statement(self)
        if token.text in TYPES:
            offset = 3 if self.peek(1).text == "[" and self.peek(2).text == "]" else 1
            if self.peek(offset + 1).text == "(":
                return c_family.function(self)
            node = c_family.declaration(self)
            self.end(True)
            return self.record(node, "shared-c", "typed-declaration", ["type keyword and semicolon"])
        if token.text == "def":
            return python_family.function(self)
        if token.text in ("if", "while"):
            return self.control()
        if token.text == "for":
            return c_family.for_loop(self) if self.peek(1).text == "(" else python_family.for_loop(self)
        if token.text in ("std", "cout", "System"):
            return c_family.output(self)
        if token.text in ("return", "break", "continue"):
            start = self.take()
            value = expression(self) if start.text == "return" and not self.at("NEWLINE") and not self.at(";") else None
            node = Node(start.text.capitalize(), self.join(start.span, value.span if value else start.span), {"value": value})
            self.end()
            return self.record(node, "shared", start.text, ["shared control statement"])
        if token.text == "print":
            start = self.take()
            args = self.arguments()
            node = Node("Output", self.join(start.span, self.previous().span), {"args": args, "separator": " " if len(args) > 1 else "", "ending": "\n"})
            self.end()
            return self.record(node, "Python", "print", ["recognized print builtin"])
        if token.kind == "NAME" and self.peek(1).text in ("=", "+=", "-=", "["):
            node = self.assignment()
            self.end()
            return self.record(node, "shared", "assignment", ["shared assignment spelling"])
        if token.kind == "NAME" and self.peek(1).text == "(":
            value = expression(self)
            node = Node("Expression", value.span, {"value": value})
            self.end()
            return self.record(node, "shared", "function-call", ["shared call spelling"])
        self.error(token, "P004", "Unsupported or malformed statement.")

polyglot/parser/python_family.py:
"""Python-inspired headers reuse shared expression and suite grammars."""

from ..ast import Node
from .shared import expression, type_spec


def annotation(p):
    return type_spec(p)


def function(p):
    start = p.expect("def")
    name = p.expect("NAME")
    p.expect("(")
    params = []
    if not p.at(")"):
        while True:
            parameter = p.expect("NAME")
            if not p.match(":"):
                p.error(p.peek(), "P020", "Function parameters require annotations.", "Write name: int (or another supported type).")
            params.append({"name": parameter.text, "type": annotation(p), "span": parameter.span})
            if not p.match(","):
                break
    p.expect(")")
    if not p.match("->"):
        p.error(p.peek(), "P020", "Functions require a return annotation.", "Add -> int, -> float, -> bool, -> string, or -> void.")
    result = annotation(p)
    if not p.at(":"):
        p.error(p.peek(), "P001", "Python-style function headers require a colon.")
    body = p.suite(start)
    node = Node("Function", p.join(start.span, body.span), {"name": name.text, "params": params, "return_type": result, "body": body})
    return p.record(node, "Python", "annotated-function", ["def, annotations, colon and indentation"])


def for_loop(p):
    start = p.expect("for")
    variable = p.expect("NAME")
    p.expect("in")
    iterable = expression(p)
    is_range = iterable.kind == "Call" and iterable.data["name"] == "range"
    if is_range and not 1 <= len(iterable.data["args"]) <= 3:
        p.error(variable, "P021", "range requires one, two, or three arguments.")
    if not p.at(":"):
        p.error(p.peek(), "P001", "Python-style for-loop headers require a colon.")
    body = p.suite(start)
    if is_range:
        node = Node("Range", p.join(start.span, body.span), {"name": variable.text, "args": iterable.data["args"], "body": body})
        return p.record(node, "Python", "range-loop", ["for/in/range and indentation"])
    node = Node("ForEach", p.join(start.span, body.span), {"name": variable.text, "iterable": iterable, "body": body})
    return p.record(node, "Python", "for-in-loop", ["for/in expression and indentation"])

polyglot/parser/shared.py:
"""One Pratt expression grammar for every syntax family."""

from ..ast import Node

TYPES = {"int": "int", "float": "float", "double": "float", "bool": "bool", "boolean": "bool",
         "str": "string", "string": "string", "String": "string", "void": "void"}
PRECEDENCE = {"or": 1, "||": 1, "and": 2, "&&": 2, "==": 4, "!=": 4, "<": 4,
              "<=": 4, ">": 4, ">=": 4, "+": 5, "-": 5, "*": 6, "/": 6, "%": 6}
COMPARISONS = {"==", "!=", "<", "<=", ">", ">="}
NORMAL = {"&&": "and", "||": "or", "!": "not"}


def type_spec(p):
    token = p.expect("NAME")
    if token.text not in TYPES:
        p.error(token, "P020", "Unknown type annotation.")
    result = TYPES[token.text]
    if p.match("["):
        p.expect("]")
        if result == "void" or p.at("["):
            p.error(token, "P025", "Arrays require one primitive element type and one dimension.")
        result += "[]"
    return result


def array_literal(p, opening="[", closing="]"):
    start = p.expect(opening)
    values = []
    p.newlines()
    if not p.at(closing):
        while True:
            values.append(expression(p))
            p.newlines()
            if not p.match(","):
                break
            p.newlines()
            if p.at(closing):
                break
    end = p.expect(closing)
    return Node("ArrayLiteral", p.join(start.span, end.span), {"values": values})


def expression(p, minimum: int = 0) -> Node:
    token = p.take()
    if token.text in ("+", "-", "not", "!"):
        right = expression(p, 3 if token.text in ("not", "!") else 7)
        left = Node("Unary", p.join(token.span, right.span), {"op": NORMAL.get(token.text, token.text), "value": right})
    elif token.kind in ("NUMBER", "STRING"):
        left = Node("Literal", token.span, {"value": token.value})
    elif token.text in ("true", "false", "True", "False"):
        left = Node("Literal", token.span, {"value": token.text in ("true", "True")})
    elif token.text == "(":
        left = expression(p)
        p.expect(")")
        left.meta["parenthesized"] = True
    elif token.text == "[":
        p.pos -= 1
        left = array_literal(p)
    elif token.text == "new":
        type_token = p.expect("NAME")
        if type_token.text not in TYPES or TYPES[type_token.text] == "void":
            p.error(type_token, "P025", "Array allocation requires a primitive element type.")
        p.expect("[")
        size = expression(p)
        end = p.expect("]")
        left = Node("ArrayNew", p.join(token.span, end.span), {"element_type": TYPES[type_token.text], "size": size})
    elif token.kind == "NAME":
        left = Node("Name", token.span, {"name": token.text})
    else:
        p.error(token, "P010", "Expected an expression.")
    while p.at("(") or p.at("["):
        if p.at("("):
            if left.kind != "Name":
                p.error(p.peek(), "P011", "Only named function calls are supported.")
            args = p.arguments()
            left = Node("Call", p.join(left.span, p.previous().span), {"name": left.data["name"], "args": args})
        else:
            p.take()
            index = expression(p)
            end = p.expect("]")
            left = Node("Index", p.join(left.span, end.span), {"array": left, "index": index})
    while p.peek().text in PRECEDENCE and PRECEDENCE[p.peek().text] >= minimum:
        op = p.take()
        if op.text in COMPARISONS and left.kind == "Binary" and left.data["op"] in COMPARISONS and not left.meta.get("parenthesized"):
            p.error(op, "P012", "Chained comparisons are unsupported.", "Combine comparisons with 'and'.")
        right = expression(p, PRECEDENCE[op.text] + 1)
        left = Node("Binary", p.join(left.span, right.span), {"op": NORMAL.get(op.text, op.text), "left": left, "right": right})
    return left

polyglot/semantics.py:
"""Shared lexical scopes, static types, and conservative control-flow analysis."""

import math
from dataclasses import dataclass, field, asdict
from .ast import Node
from .source import Source
from .diagnostics import fail
from .types import VALUE_TYPES, is_array, is_value_type, MAX_ARRAY_LENGTH
from .formats import parse_format, FormatError


@dataclass
class Symbol:
    id: int
    name: str
    type: str
    storage: str
    slot: int
    scope: int
    location: dict
    owner: int
    params: list[str] = field(default_factory=list)
    mutable: bool = True


@dataclass
class Scope:
    id: int
    parent: "Scope | None"
    owner: int
    names: dict[str, Symbol] = field(default_factory=dict)


RESERVED = {"print", "range", "cout", "endl", "std", "System", "def", "if", "elif", "else", "for", "while",
            "return", "break", "continue", "True", "False", "true", "false", "int", "float", "double", "bool",
            "boolean", "string", "str", "String", "void", "len", "new", "let", "const", "function",
            "console", "printf", "LET", "PRINT"}


class Analyzer:
    def __init__(self, source: Source):
        self.source = source
        self.symbols: list[Symbol] = []
        self.root = Scope(0, None, 0)
        self.scope = self.root
        self.scope_count = 1
        self.local_counts = {0: 0}
        self.global_count = 0
        self.assigned: set[int] = set()
        self.loop_depth = 0
        self.return_type = "void"
        self.functions: list[Node] = []

    def error(self, node: Node, code: str, message: str, suggestion: str = "", related=None):
        fail(self.source, node.span, code, message, suggestion, related)

    def enter(self):
        self.scope = Scope(self.scope_count, self.scope, self.scope.owner)
        self.scope_count += 1

    def bind(self, node: Node, name: str, type_name: str, function_id=None, params=None, mutable=True) -> Symbol:
        if name in RESERVED:
            self.error(node, "S008", f"{name!r} is reserved by the language.")
        if name in self.scope.names:
            self.error(node, "S001", f"Duplicate declaration of {name!r}.",
                       related=[self.scope.names[name].location])
        if function_id is not None:
            storage, slot = "function", function_id
            mutable = False
        elif not is_value_type(type_name):
            self.error(node, "S002", "Variables and parameters cannot have type void.")
        elif self.scope is self.root:
            storage, slot = "global", self.global_count
            self.global_count += 1
        else:
            storage, slot = "local", self.local_counts[self.scope.owner]
            self.local_counts[self.scope.owner] += 1
        symbol = Symbol(len(self.symbols), name, type_name, storage, slot, self.scope.id,
                        self.source.location(node.span), self.scope.owner, params or [], mutable)
        self.symbols.append(symbol)
        self.scope.names[name] = symbol
        return symbol

    def find(self, name: str):
        scope = self.scope
        while scope:
            if name in scope.names:
                return scope.names[name]
            scope = scope.parent
        return None

    def reference(self, node: Node, name: str) -> Symbol:
        symbol = self.find(name)
        if symbol is None:
            self.error(node, "S003", f"Undefined name {name!r}.", "Declare the name before using it.")
        return symbol

    @staticmethod
    def attach(node: Node, symbol: Symbol):
        node.meta.update({"symbol": symbol.id, "storage": symbol.storage, "slot": symbol.slot, "type": symbol.type,
                          "mutable": symbol.mutable})

    def compatible(self, node: Node, actual: str, expected: str):
        if actual != expected and not (actual == "int" and expected == "float"):
            self.error(node, "S004", f"Cannot use {actual} where {expected} is required.")

    def binary_type(self, node, op, a, b):
        numeric = a in ("int", "float") and b in ("int", "float")
        if op in ("and", "or") and a == b == "bool":
            return "bool"
        if op in ("==", "!=") and (numeric or a == b != "void") and not is_array(a) and not is_array(b):
            return "bool"
        if op in ("<", "<=", ">", ">=") and (numeric or a == b == "string"):
            return "bool"
        if op == "+" and a == b == "string":
            return "string"
        if op in ("+", "-", "*", "/", "%") and numeric:
            return "float" if op == "/" or "float" in (a, b) else "int"
        self.error(node, "S006", f"Invalid operator {op} for {a} and {b}.")

    def array_size(self, node):
        if self.expr(node) != "int":
            self.error(node, "S023", "Array length must have type int.")
        if node.kind == "Literal" and not 0 <= node.data["value"] <= MAX_ARRAY_LENGTH:
            self.error(node, "S025", f"Array length must be between 0 and {MAX_ARRAY_LENGTH}.")

    def readable(self, node: Node, symbol: Symbol):
        if symbol.storage == "function":
            self.error(node, "S007", "Functions are callable names, not first-class values.")
        if symbol.id not in self.assigned and not (self.scope.owner != 0 and symbol.storage == "global"):
            self.error(node, "S005", f"Variable {symbol.name!r} may be uninitialized.",
                       "Assign a value on every path before reading it.")

    def expr(self, node: Node, expected: str | None = None) -> str:
        d = node.data
        if node.kind == "Literal":
            t = {bool: "bool", int: "int", float: "float", str: "string"}[type(d["value"])]
            if t == "float" and not math.isfinite(d["value"]):
                self.error(node, "S009", "Nonfinite floating-point literal.")
        elif node.kind == "ArrayLiteral":
            values = d["values"]
            if any(value.kind in ("ArrayLiteral", "ArrayNew") for value in values):
                self.error(node, "S022", "Nested arrays are unsupported.")
            if len(values) > MAX_ARRAY_LENGTH:
                self.error(node, "S025", f"Arrays may contain at most {MAX_ARRAY_LENGTH} elements.")
            types = [self.expr(value) for value in values]
            if any(t not in VALUE_TYPES for t in types):
                self.error(node, "S022", "Arrays must contain primitive values; nested arrays are unsupported.")
            if is_array(expected):
                element = expected[:-2]
            elif not types:
                self.error(node, "S021", "Cannot infer the element type of an empty array.", "Use an explicit declaration such as int[] values = [];")
            elif all(t in ("int", "float") for t in types):
                element = "float" if "float" in types else "int"
            elif len(set(types)) == 1:
                element = types[0]
            else:
                self.error(node, "S022", "Array elements must have one compatible primitive type.")
            for value, actual in zip(values, types):
                self.compatible(value, actual, element)
            node.meta["element_type"] = element
            t = element + "[]"
        elif node.kind == "ArrayNew":
            self.array_size(d["size"])
            t = d["element_type"] + "[]"
            node.meta["element_type"] = d["element_type"]
        elif node.kind == "Index":
            array_type = self.expr(d["array"])
            if not is_array(array_type):
                self.error(node, "S019", "Indexing requires a one-dimensional array.")
            if self.expr(d["index"]) != "int":
                self.error(d["index"], "S020", "Array indexes must have type int.")
            t = array_type[:-2]
        elif node.kind == "Name":
            symbol = self.reference(node, d["name"])
            self.readable(node, symbol)
            self.attach(node, symbol)
            t = symbol.type
        elif node.kind == "Call":
            if d["name"] == "len":
                if len(d["args"]) != 1:
                    self.error(node, "S011", "len expects exactly one array argument.")
                if not is_array(self.expr(d["args"][0])):
                    self.error(node, "S019", "len requires an array.")
                node.meta.update({"builtin": "len", "type": "int"})
                return "int"
            symbol = self.reference(node, d["name"])
            if symbol.storage != "function":
                self.error(node, "S010", f"{symbol.name!r} is not a function.")
            if len(d["args"]) != len(symbol.params):
                self.error(node, "S011", f"{symbol.name} expects {len(symbol.params)} arguments, got {len(d['args'])}.")
            for arg, expected in zip(d["args"], symbol.params):
                self.compatible(arg, self.expr(arg, expected), expected)
            node.meta.update({"function": symbol.slot, "param_types": symbol.params})
            t = symbol.type
        elif node.kind == "Unary":
            t = self.expr(d["value"])
            if (d["op"] == "not" and t != "bool") or (d["op"] != "not" and t not in ("int", "float")):
                self.error(node, "S006", f"Invalid unary operator {d['op']} for {t}.")
        elif node.kind == "Binary":
            a, b, op = self.expr(d["left"]), self.expr(d["right"]), d["op"]
            t = self.binary_type(node, op, a, b)
        else:
            self.error(node, "S007", "Unsupported expression.")
        node.meta["type"] = t
        return t

    def condition(self, node: Node):
        if self.expr(node) != "bool":
            self.error(node, "S012", "Conditions must have type bool.")

    def block(self, block: Node, new_scope=True) -> bool:
        old_scope = self.scope
        if new_scope:
            self.enter()
        falls = True
        for node in block.data["body"]:
            current_falls = self.statement(node)
            falls = falls and current_falls
        self.scope = old_scope
        return falls

    def statement(self, node: Node) -> bool:
        d = node.data
        if node.kind == "Function":
            self.error(node, "S013", "Nested functions are unsupported.")
        if node.kind in ("Declare", "Assign"):
            existing = self.find(d["name"]) if node.kind == "Assign" else None
            expected = d["type"] if node.kind == "Declare" else existing.type if existing else None
            value_type = self.expr(d["value"], expected) if d.get("value") else None
            if d.get("size") is not None:
                self.array_size(d["size"])
                if d["size"].kind == "Literal" and d["value"].kind == "ArrayLiteral" and d["size"].data["value"] != len(d["value"].data["values"]):
                    self.error(node, "S026", "Array initializer length does not match the declared length.")
            if node.kind == "Declare":
                symbol = self.bind(node, d["name"], d["type"] or value_type, mutable=d.get("mutable", True))
            else:
                symbol = self.find(d["name"])
                if symbol is None:
                    if d["op"] != "=":
                        self.error(node, "S003", "Compound assignment requires an existing variable.")
                    symbol = self.bind(node, d["name"], value_type)
                elif symbol.storage == "function":
                    self.error(node, "S004", "Cannot assign to a function.")
                elif not symbol.mutable:
                    self.error(node, "S028", f"Cannot reassign const binding {symbol.name!r}.",
                               "Use let if the binding must be reassigned.", related=[symbol.location])
            if d.get("op") in ("+=", "-="):
                old = Node("Name", node.span, {"name": d["name"]})
                binary = Node("Binary", node.span, {"op": d["op"][0], "left": old, "right": d["value"]})
                value_type = self.expr(binary)
                d["value"] = binary
            self.attach(node, symbol)
            if value_type is not None:
                self.compatible(node, value_type, symbol.type)
                self.assigned.add(symbol.id)
        elif node.kind == "IndexAssign":
            target_type = self.expr(d["target"])
            value_type = self.expr(d["value"])
            result_type = value_type if d["op"] == "=" else self.binary_type(node, d["op"][0], target_type, value_type)
            self.compatible(node, result_type, target_type)
            node.meta.update({"type": target_type, "operation_type": result_type})
        elif node.kind == "Output":
            for arg in d["args"]:
                if self.expr(arg) == "void":
                    self.error(arg, "S006", "Cannot print a void value.")
        elif node.kind == "OutputSequence":
            for piece in d["body"]:
                self.statement(piece)
        elif node.kind == "Printf":
            format_node = d["format"]
            if format_node.kind != "Literal" or type(format_node.data["value"]) is not str:
                self.error(format_node, "S029", "printf requires a literal format string.")
            self.expr(format_node)
            try:
                segments, types = parse_format(format_node.data["value"])
            except FormatError as exc:
                self.error(format_node, "S029", str(exc), "Supported formats: %d, %f, %s and %%.")
            if len(d["args"]) != len(types):
                self.error(node, "S011", f"printf format expects {len(types)} arguments, got {len(d['args'])}.")
            for arg, expected in zip(d["args"], types):
                self.compatible(arg, self.expr(arg), expected)
            node.meta.update({"segments": segments, "format_types": types})
        elif node.kind == "Expression":
            self.expr(d["value"])
        elif node.kind == "If":
            before = set(self.assigned)
            exits = []
            for branch in d["branches"]:
                self.assigned = set(before)
                self.condition(branch["condition"])
                falls = self.block(branch["body"])
                if falls:
                    exits.append(set(self.assigned))
            self.assigned = set(before)
            if d["else"]:
                if self.block(d["else"]):
                    exits.append(set(self.assigned))
            else:
                exits.append(before)
            self.assigned = set.intersection(*exits) if exits else before
            return bool(exits)
        elif node.kind in ("While", "For", "Range", "ForEach"):
            old_scope, before = self.scope, set(self.assigned)
            self.enter()
            if node.kind == "Range":
                for arg in d["args"]:
                    if self.expr(arg) != "int":
                        self.error(arg, "S014", "range arguments must be integers.")
                symbol = self.bind(node, d["name"], "int")
                self.attach(node, symbol)
                self.assigned.add(symbol.id)
                after = before
            elif node.kind == "ForEach":
                iterable_type = self.expr(d["iterable"])
                if not is_array(iterable_type):
                    self.error(d["iterable"], "S027", "Python-style for-in iteration requires an array.",
                               "Iterate over an array, or use for name in range(...).")
                symbol = self.bind(node, d["name"], iterable_type[:-2])
                self.attach(node, symbol)
                self.assigned.add(symbol.id)
                after = before
            elif node.kind == "For":
                if d["initial"]:
                    self.statement(d["initial"])
                self.condition(d["condition"])
                after = set(self.assigned)
            else:
                self.condition(d["condition"])
                after = before
            self.loop_depth += 1
            self.block(d["body"])
            if node.kind == "For" and d["update"]:
                # An update may be reached through continue, so do not rely on body-only initialization.
                self.assigned = set(after)
                self.statement(d["update"])
            self.loop_depth -= 1
            self.scope, self.assigned = old_scope, after
        elif node.kind in ("Break", "Continue"):
            if not self.loop_depth:
                self.error(node, "S015", f"{node.kind.lower()} is only valid inside a loop.")
            return False
        elif node.kind == "Return":
            if self.scope.owner == 0:
                self.error(node, "S016", "return is only valid inside a function.")
            if d["value"] is None:
                if self.return_type != "void":
                    self.error(node, "S017", "A value-returning function must return a value.")
            elif self.return_type == "void":
                self.error(node, "S017", "A void function cannot return a value.")
            else:
                self.compatible(node, self.expr(d["value"], self.return_type), self.return_type)
            return False
        else:
            self.error(node, "S007", f"Unsupported AST node {node.kind}.")
        return True

    def analyze(self, program: Node):
        for node in program.data["body"]:
            if node.kind == "Function":
                fid = len(self.functions) + 1
                symbol = self.bind(node, node.data["name"], node.data["return_type"], fid,
                                   [p["type"] for p in node.data["params"]])
                self.attach(node, symbol)
                node.meta["function"] = fid
                self.functions.append(node)
        for node in program.data["body"]:
            if node.kind != "Function":
                self.statement(node)
        for node in self.functions:
            fid = node.meta["function"]
            self.local_counts[fid] = 0
            self.scope = Scope(self.scope_count, self.root, fid)
            self.scope_count += 1
            self.assigned = set()
            self.return_type = node.data["return_type"]
            for param in node.data["params"]:
                site = Node("Parameter", param["span"])
                symbol = self.bind(site, param["name"], param["type"])
                param["binding"] = asdict(symbol)
                self.assigned.add(symbol.id)
            if self.block(node.data["body"], new_scope=False) and self.return_type != "void":
                self.error(node, "S018", "A value-returning function may reach its end without returning.",
                           "Return a compatible value on every path; loop termination is checked conservatively.")
        self.scope = self.root
        return [asdict(s) for s in self.symbols]

polyglot/source.py:
"""Source positions shared by every compiler stage."""

from bisect import bisect_right
from dataclasses import dataclass, asdict


@dataclass(frozen=True)
class Span:
    filename: str
    start: int
    end: int
    line: int
    column: int
    end_line: int
    end_column: int


class Source:
    def __init__(self, text: str, filename: str = "program.poly"):
        self.text = text
        self.filename = filename
        self.lines = text.splitlines()
        self.starts = [0] + [i + 1 for i, c in enumerate(text) if c == "\n"]

    def span(self, start: int, end: int) -> Span:
        a = bisect_right(self.starts, start) - 1
        b = bisect_right(self.starts, end) - 1
        return Span(self.filename, start, end, a + 1, start - self.starts[a] + 1,
                    b + 1, end - self.starts[b] + 1)

    def excerpt(self, span: Span) -> str:
        return self.lines[span.line - 1] if 0 < span.line <= len(self.lines) else ""

    def location(self, span: Span) -> dict:
        return {**asdict(span), "excerpt": self.excerpt(span)}

polyglot/types.py:
"""Common primitive and one-dimensional array types."""

VALUE_TYPES = ("int", "float", "bool", "string")
MAX_ARRAY_LENGTH = 1_000
MAX_ARRAY_ELEMENTS = 100_000


def is_array(type_name: str) -> bool:
    return isinstance(type_name, str) and type_name.endswith("[]") and type_name[:-2] in VALUE_TYPES


def is_value_type(type_name: str) -> bool:
    return type_name in VALUE_TYPES or is_array(type_name)

polyglot/vm.py:
"""Validated stack bytecode execution, call frames, guards, and resource limits."""

import math
import json
import time
from dataclasses import dataclass, field
from .artifact import validate
from .diagnostics import Diagnostic, PolyglotError
from .types import MAX_ARRAY_LENGTH, MAX_ARRAY_ELEMENTS
from .formats import FORMAT_TYPES

UNINITIALIZED = object()


@dataclass
class ArrayValue:
    element_type: str
    values: list


@dataclass
class Limits:
    steps: int = 1_000_000
    recursion: int = 64
    output: int = 65536
    timeout: float = 5.0


@dataclass
class Frame:
    function: dict
    locals: list
    ip: int = 0
    stack: list = field(default_factory=list)
    callsite: dict | None = None


def type_name(value):
    if isinstance(value, ArrayValue):
        return value.element_type + "[]"
    return {bool: "bool", int: "int", float: "float", str: "string"}.get(type(value))


def format_value(value):
    if isinstance(value, ArrayValue):
        return json.dumps(value.values, ensure_ascii=False, allow_nan=False)
    return "true" if value is True else "false" if value is False else str(value)


def run(artifact: dict, limits: Limits | None = None) -> dict:
    validate(artifact)
    limits = limits or Limits()
    if (any(type(v) is not int for v in (limits.steps, limits.recursion, limits.output))
            or type(limits.timeout) not in (int, float) or not math.isfinite(limits.timeout)
            or min(limits.steps, limits.recursion, limits.output, limits.timeout) <= 0):
        raise ValueError("Execution limits must be positive.")
    globals_ = [UNINITIALIZED] * artifact["global_count"]
    fn = artifact["functions"][artifact["entry"]]
    frames = [Frame(fn, [UNINITIALIZED] * fn["local_count"])]
    output, steps, output_size = [], 0, 0
    allocated_elements = 0
    started = time.monotonic()
    while frames:
        frame = frames[-1]
        instruction = frame.function["code"][frame.ip]
        frame.ip += 1
        steps += 1
        op, args = instruction["op"], instruction["args"]

        def error(code, message):
            stack = [{"function": f.function["name"], **(f.callsite or instruction["source"])}
                     for f in reversed(frames)]
            failure = PolyglotError(Diagnostic(code, message, instruction["source"], stack=stack))
            failure.output = "".join(output)
            raise failure

        def checked(value):
            if type(value) is float and not math.isfinite(value):
                error("R005", "Nonfinite numeric result.")
            if type(value) is str and len(value.encode("utf-8")) > 131072:
                error("R010", "String value exceeds the 128 KiB resource limit.")
            if type(value) is int and value.bit_length() > 1_000_000:
                error("R010", "Integer value exceeds the execution resource limit.")
            return value

        def array_index(array, index):
            if not isinstance(array, ArrayValue) or type(index) is not int:
                error("R007", "Array access requires an array and an integer index.")
            if not 0 <= index < len(array.values):
                error("R012", f"Array index {index} is outside bounds [0, {len(array.values)}).")

        def array_size(size):
            if type(size) is not int or not 0 <= size <= MAX_ARRAY_LENGTH:
                error("R013", f"Array length must be an integer between 0 and {MAX_ARRAY_LENGTH}.")

        def allocate(element, values):
            nonlocal allocated_elements
            array_size(len(values))
            if any(type_name(v) != element for v in values):
                error("R007", "Array elements have incompatible types.")
            allocated_elements += max(1, len(values))
            if allocated_elements > MAX_ARRAY_ELEMENTS:
                error("R013", "Array allocation budget exceeded.")
            return ArrayValue(element, values)

        if steps > limits.steps:
            error("R001", "Instruction execution limit exceeded.")
        if time.monotonic() - started > limits.timeout:
            error("R002", "Execution timeout exceeded.")
        try:
            if op == "CONST":
                frame.stack.append(checked(artifact["constants"][args[0]]["value"]))
            elif op.startswith("LOAD_"):
                value = (globals_ if op.endswith("GLOBAL") else frame.locals)[args[0]]
                if value is UNINITIALIZED:
                    error("R003", "Read of an uninitialized variable.")
                frame.stack.append(value)
            elif op.startswith("STORE_"):
                (globals_ if op.endswith("GLOBAL") else frame.locals)[args[0]] = frame.stack.pop()
            elif op == "POP":
                frame.stack.pop()
            elif op == "UNARY":
                v, operator = frame.stack.pop(), args[0]
                if operator == "not":
                    if type(v) is not bool:
                        error("R007", "Logical negation requires a Boolean.")
                    value = not v
                else:
                    if type(v) not in (int, float):
                        error("R007", "Numeric unary operation requires a number.")
                    value = float(v) if operator == "float" else -v if operator == "-" else +v
                frame.stack.append(checked(value))
            elif op == "BINARY":
                b, a = frame.stack.pop(), frame.stack.pop()
                operator = args[0]
                numeric = type(a) in (int, float) and type(b) in (int, float)
                if operator in ("and", "or"):
                    if type(a) is not bool or type(b) is not bool:
                        error("R007", "Boolean operation requires Booleans.")
                elif operator in ("==", "!="):
                    if isinstance(a, ArrayValue) or isinstance(b, ArrayValue) or not (numeric or type_name(a) == type_name(b)):
                        error("R007", "Comparison operands have incompatible types.")
                elif not numeric and not (type(a) is type(b) is str and operator in ("+", "<", "<=", ">", ">=")):
                    error("R007", "Operands have incompatible types.")
                if operator in ("/", "%") and b == 0:
                    error("R004", "Division or remainder by zero.")
                if operator == "%":
                    value = (abs(a) % abs(b)) * (-1 if a < 0 else 1) if type(a) is type(b) is int else math.fmod(a, b)
                else:
                    value = {"+": lambda: a + b, "-": lambda: a - b, "*": lambda: a * b, "/": lambda: a / b,
                             "==": lambda: a == b, "!=": lambda: a != b, "<": lambda: a < b, "<=": lambda: a <= b,
                             ">": lambda: a > b, ">=": lambda: a >= b, "and": lambda: a and b, "or": lambda: a or b}[operator]()
                frame.stack.append(checked(value))
            elif op == "FORMAT":
                value = frame.stack.pop()
                if type_name(value) != FORMAT_TYPES[args[0]]:
                    error("R007", "Formatting value has an incompatible type.")
                rendered = format(value, ".6f") if args[0] == "f" else str(value)
                frame.stack.append(checked(rendered))
            elif op == "ARRAY_BUILD":
                values = [frame.stack.pop() for _ in range(args[1])][::-1]
                frame.stack.append(allocate(args[0], values))
            elif op == "ARRAY_NEW":
                size = frame.stack.pop()
                array_size(size)
                default = {"int": 0, "float": 0.0, "bool": False, "string": ""}[args[0]]
                frame.stack.append(allocate(args[0], [default] * size))
            elif op in ("ARRAY_GET", "ARRAY_SET", "ARRAY_CHECK"):
                value = frame.stack.pop() if op == "ARRAY_SET" else None
                index, array = frame.stack.pop(), frame.stack.pop()
                array_index(array, index)
                if op == "ARRAY_GET":
                    frame.stack.append(array.values[index])
                elif op == "ARRAY_SET":
                    if type_name(value) != array.element_type:
                        error("R007", "Array element assignment has an incompatible type.")
                    array.values[index] = checked(value)
            elif op == "ARRAY_LENGTH":
                array = frame.stack.pop()
                if not isinstance(array, ArrayValue):
                    error("R007", "Array length requires an array.")
                frame.stack.append(len(array.values))
            elif op == "ARRAY_SIZE_CHECK":
                size, array = frame.stack.pop(), frame.stack.pop()
                array_size(size)
                if not isinstance(array, ArrayValue):
                    error("R007", "Array size validation requires an array.")
                if size != len(array.values):
                    error("R014", "Array initializer length does not match the declared length.")
            elif op in ("JUMP", "JUMP_IF_FALSE"):
                if op == "JUMP":
                    frame.ip = args[0]
                else:
                    condition = frame.stack.pop()
                    if type(condition) is not bool:
                        error("R007", "Branch condition must be a Boolean.")
                    if not condition:
                        frame.ip = args[0]
            elif op == "CALL":
                if len(frames) - 1 >= limits.recursion:
                    error("R011", "Recursion/call-depth limit exceeded.")
                values = [frame.stack.pop() for _ in range(args[1])][::-1]
                callee = artifact["functions"][args[0]]
                if [type_name(v) for v in values] != callee["params"]:
                    error("R007", "Bytecode call has incompatible argument types.")
                locals_ = [UNINITIALIZED] * callee["local_count"]
                locals_[:len(values)] = values
                frames.append(Frame(callee, locals_, callsite=instruction["source"]))
            elif op in ("RETURN_VALUE", "RETURN_VOID"):
                value = frame.stack.pop() if op == "RETURN_VALUE" else None
                if op == "RETURN_VALUE" and type_name(value) != frame.function["return_type"]:
                    error("R007", "Bytecode return type is incompatible.")
                frames.pop()
                if frames and op == "RETURN_VALUE":
                    frames[-1].stack.append(value)
            elif op == "OUTPUT":
                values = [frame.stack.pop() for _ in range(args[0])][::-1]
                rendered = args[1].join(format_value(v) for v in values) + args[2]
                output_size += len(rendered.encode("utf-8"))
                if output_size > limits.output:
                    error("R006", "Output size limit exceeded.")
                output.append(rendered)
            elif op == "ASSERT":
                condition = frame.stack.pop()
                if type(condition) is not bool:
                    error("R007", "Runtime guard requires a Boolean.")
                if not condition:
                    error(args[0], args[1])
            elif op == "TRAP":
                error(args[0], args[1])
        except (IndexError, TypeError, ValueError, OverflowError, ZeroDivisionError) as exc:
            error("R007", f"Invalid runtime operation: {exc}")
    return {"output": "".join(output), "steps": steps}

polyglot/web/worker.py:
"""Spawned jobs share the compiler API; no shell or host-source execution."""

from dataclasses import asdict
import math
from ..compiler import compile_source
from ..artifact import loads, dumps, ArtifactError
from ..diagnostics import Diagnostic, PolyglotError
from ..vm import run, Limits


def execution_limits(payload):
    values = payload.get("limits", {})
    if not isinstance(values, dict) or set(values) - {"steps", "recursion", "output", "timeout"}:
        raise ValueError("Invalid execution limits.")
    defaults = asdict(Limits())
    for name, value in values.items():
        if name == "timeout":
            valid = type(value) in (int, float) and math.isfinite(value)
        else:
            valid = type(value) is int
        if not valid or not 0 < value <= defaults[name]:
            raise ValueError(f"{name} must be positive and no greater than {defaults[name]}.")
        defaults[name] = value
    return Limits(**defaults)


def execute_job(operation: str, payload: dict) -> dict:
    location = {"filename": payload.get("filename", "program.poly"), "line": 1, "column": 1, "excerpt": ""}
    try:
        if operation == "exec":
            artifact_text = payload.get("artifact")
            if not isinstance(artifact_text, str):
                raise ValueError("artifact must be JSON text")
            artifact = loads(artifact_text)
            result = {"ok": True, "diagnostics": [], "stages": {"bytecode": artifact}, "artifact": artifact}
        else:
            source = payload.get("source")
            filename = payload.get("filename", "program.poly")
            if not isinstance(source, str) or not isinstance(filename, str) or len(filename) > 256:
                raise ValueError("source and filename must be strings")
            result = compile_source(source, filename, optimize=payload.get("optimize", True))
            artifact = result["artifact"]
        result["output"] = ""
        if not result["ok"]:
            return result
        if operation in ("run", "exec"):
            result.update(run(artifact, execution_limits(payload)))
        if operation == "build":
            result["artifact_text"] = dumps(artifact)
        return result
    except PolyglotError as exc:
        if "result" not in locals():
            result = {"stages": {}, "artifact": None}
        return {**result, "ok": False, "output": getattr(exc, "output", ""), "diagnostics": [asdict(exc.diagnostic)]}
    except (ArtifactError, ValueError, TypeError) as exc:
        return {"ok": False, "output": "", "stages": {}, "artifact": None,
                "diagnostics": [asdict(Diagnostic("A001", str(exc), location))]}


def worker(connection, operation, payload):
    try:
        connection.send(execute_job(operation, payload))
    except Exception:
        connection.send({"ok": False, "output": "", "stages": {}, "artifact": None,
                         "diagnostics": [{"code": "C999", "message": "Internal compiler error. Report this program as a defect.",
                                          "location": {"filename": "program.poly", "line": 1, "column": 1, "excerpt": ""}}]})
    finally:
        connection.close()
